// osCommand adapts *exec.Cmd to tea.ExecCommand: a stream is set only when nil.
type osCommand struct{ *exec.Cmd }

func (c osCommand) SetStdin(io.Reader)  {}
func (c osCommand) SetStdout(io.Writer) {}
func (c osCommand) SetStderr(io.Writer) {}
